fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Number of input rows and columns
    let rows = x.len();
    let cols = x[0].len(); // safe because x has at least one row with at least one element

    // Prepare the output matrix with `cols` rows, each with capacity for `rows` elements
    let mut result: Vec<Vec<f32>> = Vec::with_capacity(cols);
    for c in 0..cols {
        let mut new_row = Vec::with_capacity(rows);
        for r in 0..rows {
            // transpose: element at (c, r) in the result comes from (r, c) in the input
            new_row.push(x[r][c]);
        }
        result.push(new_row);
    }

    result
}

